add_action('init',function(){if(!function_exists('wc_get_product')||get_option('bhc_samsung_images_v354_done'))return;$items=[27=>['file'=>'samsung-vcc4190v37xsg-v354.png','prompt'=>'Samsung VCC4190V37/XSG SC4190 red 2000W bagged canister vacuum with 3L bag, exact model-specific transparent 4K ecommerce cutout'],343=>['file'=>'samsung-q1470hc-v354.png','prompt'=>'Samsung Q1470/HC front-load washing machine, exact model-specific white appliance with round door, transparent 4K ecommerce cutout']];$dir=plugin_dir_path(__FILE__).'bhc-image-references/';if(!is_dir($dir))wp_mkdir_p($dir);require_once ABSPATH.'wp-admin/includes/image.php';$ok=0;foreach($items as $id=>$row){$path=$dir.$row['file'];if(!file_exists($path))continue;$old=get_post_thumbnail_id($id);if($old)wp_delete_attachment($old,true);$u=wp_upload_bits($row['file'],null,file_get_contents($path));if(!empty($u['error']))continue;$type=wp_check_filetype($u['file'],null);$aid=wp_insert_attachment(['post_mime_type'=>$type['type'],'post_title'=>get_the_title($id).' تصویر اختصاصی','post_status'=>'inherit'],$u['file'],$id);wp_update_attachment_metadata($aid,wp_generate_attachment_metadata($aid,$u['file']));set_post_thumbnail($id,$aid);update_post_meta($id,'_bhc_image_generation_status','generated_4k_transparent_verified');update_post_meta($id,'_bhc_image_prompt',$row['prompt'].'؛ PNG شفاف، بدون متن و واترمارک.');update_post_meta($id,'_bhc_image_checked_at','2026-11-20');$ok++;}update_option('bhc_samsung_images_v354_done',$ok===count($items)?1:0,false);});
